export const UI_SHAPE_ICONS: readonly UiShapeIconDefinition[] = [
  ...UI_SHAPE_PIXELART_ICONS,
  ...UI_SHAPE_WIN98_ICONS,
];

export const DEFAULT_UI_SHAPE_ICON_ID = 'computer16';

const ICONS_BY_ID = new Map(UI_SHAPE_ICONS.map((icon) => [icon.id, icon]));
const PIXEL_CACHE = new Map<string, Uint8Array>();
const ICON_MATCH_CACHE = new Map<string, string>();
const ICON_MATCH_CACHE_LIMIT = 4_096;

const decodePixels = (icon: UiShapeIconDefinition): Uint8Array => {
  const cached = PIXEL_CACHE.get(icon.id);
  if (cached) return cached;
  const binary = globalThis.atob(icon.pixels);
  const encoded = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  const pixels = icon.encoding === 'rle'
    ? (() => {
        const decoded = new Uint8Array(icon.width * icon.height);
        let offset = 0;
        for (let index = 0; index < encoded.length; index += 2) {
          const runLength = encoded[index] ?? 0;
          const paletteIndex = encoded[index + 1] ?? 0;
          decoded.fill(paletteIndex, offset, offset + runLength);
          offset += runLength;
        }
        return decoded;
      })()
    : encoded;
  PIXEL_CACHE.set(icon.id, pixels);
  return pixels;
};

export const normalizeUiShapeIconId = (value: unknown): string => (
  typeof value === 'string' && ICONS_BY_ID.has(value)
    ? value
    : DEFAULT_UI_SHAPE_ICON_ID
);

export const getUiShapeIcon = (value: unknown): UiShapeIconDefinition => (
  ICONS_BY_ID.get(normalizeUiShapeIconId(value))!
);

export const drawUiShapeIcon = (
  context: UiShapeIconCanvasContext,
  iconId: unknown,
  x: number,
  y: number,
  width: number,
  height: number,
): void => {
  const icon = getUiShapeIcon(iconId);
  const targetWidth = Math.max(1, Math.floor(width));
  const targetHeight = Math.max(1, Math.floor(height));
  const scale = Math.min(targetWidth / icon.width, targetHeight / icon.height);
  const drawWidth = scale >= 1
    ? Math.max(1, icon.width * Math.floor(scale))
    : Math.max(1, Math.floor(icon.width * scale));
  const drawHeight = scale >= 1
    ? Math.max(1, icon.height * Math.floor(scale))
    : Math.max(1, Math.floor(icon.height * scale));
  const left = Math.round(x + (width - drawWidth) / 2);
  const top = Math.round(y + (height - drawHeight) / 2);
  const pixels = decodePixels(icon);
  for (let targetY = 0; targetY < drawHeight; targetY += 1) {
    const sourceY = Math.min(icon.height - 1, Math.floor(targetY * icon.height / drawHeight));
    let runStart = 0;
    let runColor = pixels[sourceY * icon.width]!;
    for (let targetX = 1; targetX <= drawWidth; targetX += 1) {
      const sourceX = Math.min(icon.width - 1, Math.floor(targetX * icon.width / drawWidth));
      const color = targetX < drawWidth
        ? pixels[sourceY * icon.width + sourceX]!
        : -1;
      if (color === runColor) continue;
      if (runColor !== 0) {
        context.fillStyle = icon.palette[runColor]!;
        context.fillRect(left + runStart, top + targetY, targetX - runStart, 1);
      }
      runStart = targetX;
      runColor = color;
    }
  }
};

interface OklabColor {
  lightness: number;
  a: number;
  b: number;
  chroma: number;
}

const parseHex = (value: string): [number, number, number] | null => {
  const match = value.trim().match(/^#([\da-f]{6})$/i);
  if (!match) return null;
  const packed = Number.parseInt(match[1]!, 16);
  return [(packed >> 16) & 255, (packed >> 8) & 255, packed & 255];
};

const srgbToLinear = (value: number): number => {
  const channel = value / 255;
  return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
};

const toOklab = ([red, green, blue]: [number, number, number]): OklabColor => {
  const r = srgbToLinear(red);
  const g = srgbToLinear(green);
  const b = srgbToLinear(blue);
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const lab = {
    lightness: 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    a: 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    b: 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
    chroma: 0,
  };
  lab.chroma = Math.hypot(lab.a, lab.b);
  return lab;
};

export const resolveUiShapeIconForSamples = (
  samples: readonly string[],
  fallback: unknown = DEFAULT_UI_SHAPE_ICON_ID,
): string => {
  const normalizedFallback = normalizeUiShapeIconId(fallback);
  const cacheKey = `${normalizedFallback}\u0000${samples.join('\u0000')}`;
  const cached = ICON_MATCH_CACHE.get(cacheKey);
  if (cached) return cached;
  const colors = samples.flatMap((sample) => {
    const parsed = parseHex(sample);
    return parsed ? [toOklab(parsed)] : [];
  });
  if (colors.length === 0) return normalizedFallback;
  const target = colors.reduce<OklabColor>((total, color) => ({
    lightness: total.lightness + color.lightness / colors.length,
    a: total.a + color.a / colors.length,
    b: total.b + color.b / colors.length,
    chroma: total.chroma + color.chroma / colors.length,
  }), { lightness: 0, a: 0, b: 0, chroma: 0 });
  let best = getUiShapeIcon(normalizedFallback);
  let bestScore = Number.POSITIVE_INFINITY;
  UI_SHAPE_ICONS.forEach((icon) => {
    const lightnessDistance = Math.abs(icon.signature.lightness - target.lightness);
    const hueDistance = Math.hypot(icon.signature.a - target.a, icon.signature.b - target.b);
    const chromaDistance = Math.abs(icon.signature.chroma - target.chroma);
    const score = lightnessDistance * 1.35 + hueDistance * 1.8 + chromaDistance * 0.35;
    if (score < bestScore) {
      best = icon;
      bestScore = score;
    }
  });
  if (ICON_MATCH_CACHE.size >= ICON_MATCH_CACHE_LIMIT) {
    const oldest = ICON_MATCH_CACHE.keys().next().value;
    if (oldest) ICON_MATCH_CACHE.delete(oldest);
  }
  ICON_MATCH_CACHE.set(cacheKey, best.id);
  return best.id;
};

export const resolveUiShapeIconForSampleRegion = ({
  x,
  y,
  width,
  height,
  sampleColorAtPosition,
  fallback,
}: {
  x: number;
  y: number;
  width: number;
  height: number;
  sampleColorAtPosition: (x: number, y: number) => string;
  fallback?: unknown;
}): string => {
  const fractions = [0.16, 0.5, 0.84];
  const samples = fractions.flatMap((vertical) => fractions.map((horizontal) => (
    sampleColorAtPosition(x + width * horizontal, y + height * vertical)
  )));
  return resolveUiShapeIconForSamples(samples, fallback);
};
